CREATE TABLE `정시기본` (
  `U_ID` int NOT NULL,
  `학년도` int NOT NULL,
  `군` text,
  `형태` text,
  `광역` text,
  `시구` text,
  `입학처` text,
  `대학명` text,
  `학과명` text,
  `모집정원` text,
  `logo_url` varchar(255) DEFAULT NULL,
  `교직` text,
  `단계별` text,
  `tags` json DEFAULT NULL COMMENT '학과 라벨 (예: 군이동, 신규, 실기변경 등)',
  `실기종목_display` text COMMENT '학년도별 모집요강 표시용 (정식명, 정시실기배점과 별개)',
  `실기종목_diff_note` text COMMENT '27 vs 26 실기종목 차이 메모 (사람이 읽는 텍스트, 미리 계산됨)',
  PRIMARY KEY (`U_ID`,`학년도`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `정시반영비율` (
  `id` int NOT NULL AUTO_INCREMENT,
  `학년도` int NOT NULL,
  `계산방식` varchar(20) NOT NULL DEFAULT '환산',
  `총점` int NOT NULL DEFAULT '1000',
  `계산유형` varchar(20) NOT NULL DEFAULT '기본비율',
  `U_ID` int DEFAULT NULL,
  `반영방법` text,
  `수능` text,
  `내신` text,
  `실기` text,
  `실기총점` int NOT NULL DEFAULT '0' COMMENT '실기 만점 (예: 400)',
  `선택형여부` tinyint(1) DEFAULT '0',
  `선택조건` varchar(50) DEFAULT NULL,
  `선택가중치` varchar(50) DEFAULT NULL,
  `한국사방식` varchar(20) DEFAULT NULL,
  `한국사점수` decimal(5,2) DEFAULT NULL,
  `기본점수` int NOT NULL DEFAULT '0' COMMENT '총점에 가산되는 기본점수 (0점이면 적용 안 함)',
  `미달처리` varchar(10) DEFAULT '0점' COMMENT '기준 미달 시 처리 (0점 | 최하점)',
  `기타` text,
  `국어` text,
  `수학` text,
  `영어` text,
  `탐구` text,
  `탐구수` text,
  `한국사` text,
  `english_scores` json DEFAULT NULL,
  `history_scores` json DEFAULT NULL,
  `selection_rules` json DEFAULT NULL,
  `특수공식` text,
  `기타설정` json DEFAULT NULL COMMENT '한국사우선적용 등 기타 옵션 저장용',
  `bonus_rules` json DEFAULT NULL,
  `score_config` json DEFAULT NULL,
  `실기모드` varchar(20) NOT NULL DEFAULT 'basic' COMMENT 'basic=기본비율, special=특수실기',
  `실기특수설정` json DEFAULT NULL COMMENT '특수실기용 옵션',
  PRIMARY KEY (`id`),
  KEY `idx_u_year_total` (`U_ID`,`학년도`,`총점`),
  CONSTRAINT `FK_정시반영비율_TO_정시기본_NEW` FOREIGN KEY (`U_ID`, `학년도`) REFERENCES `정시기본` (`U_ID`, `학년도`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `정시실기배점` (
  `id` int NOT NULL AUTO_INCREMENT,
  `U_ID` int NOT NULL COMMENT '정시기본 U_ID',
  `학년도` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `종목명` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `성별` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '반드시 ''남'' 또는 ''여''',
  `기록` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '숫자(12.5), P/F, A/B, 범위(200 이상) 등',
  `배점` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '숫자 점수(98) 또는 등급(PASS) 저장',
  PRIMARY KEY (`id`),
  KEY `idx_lookup` (`U_ID`,`학년도`,`종목명`,`성별`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
